"""Banco autoral piloto. A geração não constitui validação psicométrica."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / 'maeda-perfis/data'
ROOT.mkdir(parents=True, exist_ok=True)

AGREEMENT = {'1':'Discordo totalmente','2':'Discordo em parte','3':'Nem concordo nem discordo','4':'Concordo em parte','5':'Concordo totalmente'}
INTEREST = {'1':'Nenhum interesse','2':'Pouco interesse','3':'Interesse moderado','4':'Bastante interesse','5':'Muito interesse'}

def dimension(key, label, short_label, description, action, prompts):
    return dict(key=key,label=label,short_label=short_label,description=description,action=action,prompts=prompts)

def write(key, title, description, icon, color, reference, dimensions, scale=AGREEMENT, instructions='Pense nas situações do seu cotidiano e indique quanto cada afirmação descreve você hoje. Não há resposta certa nem um perfil ideal.'):
    questions=[]
    for index in range(max(len(d['prompts']) for d in dimensions)):
        for d in dimensions:
            if index >= len(d['prompts']): continue
            prompt=d['prompts'][index]
            reverse=isinstance(prompt,tuple)
            questions.append(dict(id=f'{key[:3]}_{len(questions)+1:02}',prompt=prompt[0] if reverse else prompt,dimension=d['key'],reverse=reverse))
    module=dict(key=key,version='0.1.0',title=title,description=description,icon=icon,color=color,pilot=True,reference=reference,minutes=f'{max(4,len(questions)//4)}–{max(6,len(questions)//3)}',instructions=instructions,scale=scale,dimensions=[{k:v for k,v in d.items() if k!='prompts'} for d in dimensions],questions=questions)
    (ROOT/(key+'.json')).write_text(json.dumps(module,ensure_ascii=False,indent=2)+'\n')
    print(key, len(questions), 'perguntas')

